async onEditingModeChange(editingMode) {
      if (this.isContentEditorActive && editingMode === EDITING_MODE_MARKDOWN_FIELD) {
        try {
          // The observer is debounced; read before unmounting the rich editor.
          const markdown = this.$refs.contentEditor.getSerializedContentForHandoff();
          if (typeof markdown !== 'string') throw new TypeError('EXPECTED_CURRENT_MARKDOWN');
          this.updateMarkdownFromContentEditor({ markdown });
          if (this.alert?.handoffError) this.alert = null;
        } catch {
          this.alert = {
            message: s__(
              'MarkdownEditor|Unable to switch to Markdown. Your document is still open in the rich text editor. Finish the current edit or resolve the conversion error, then try again.',
            ),
            variant: 'danger',
            handoffError: true,
            dismiss: () => {
              this.alert = null;
            },
          };
          return;
        }
      }

      if (
        editingMode === EDITING_MODE_CONTENT_EDITOR &&
        this.beforeContentEditor &&
        !(await this.beforeContentEditor(this.markdown))
      ) {
        return;
      }

      this.editingMode = editingMode;
      this.notifyEditingModeChange(editingMode);
    }

async onEditingModeRestored(editingMode) {
      if (!this.isDefaultEditorEnabled) return;
      if (this.isContentEditorActive && editingMode === EDITING_MODE_MARKDOWN_FIELD) {
        await this.onEditingModeChange(editingMode);
        return;
      }
      if (editingMode === EDITING_MODE_CONTENT_EDITOR && !this.enableContentEditor) {
        this.editingMode = EDITING_MODE_MARKDOWN_FIELD;
        return;
      }

      this.editingMode = editingMode;
      this.$emit(EDITING_MODE_EVENTS[editingMode]);
      this.notifyEditingModeChange(editingMode);
    }

getSerializedContentForHandoff() {
      if (
        this.isLoading ||
        !this.contentEditor?.tiptapEditor?.view ||
        this.contentEditor.tiptapEditor.view.composing ||
        (!this.collaborationProvider && this.latestMarkdown !== this.markdown)
      ) {
        throw new Error('MARKDOWN_SERIALIZATION_NOT_READY');
      }
      return this.contentEditor.getSerializedContent();
    }

setupSubmissionBinding() {
      this.submissionBinding = bindMarkdownSubmission({
        element: this.$el,
        read: () =>
          this.isContentEditorActive
            ? this.$refs.contentEditor.getSerializedContentForHandoff()
            : this.markdown,
        write: (markdown) => {
          if (markdown !== this.markdown) this.updateMarkdownFromContentEditor({ markdown });
          const field = this.$refs.submissionField || this.$refs.textarea;
          if (field) field.value = markdown;
        },
        onReady: () => {
          if (this.alert?.submissionError) this.alert = null;
        },
        onError: (error) => {
          let message = s__(
            'MarkdownEditor|Unable to save the current document. Finish the current edit or resolve the conversion error, then try again.',
          );
          if (error?.code === 'changed')
            message = s__(
              'MarkdownEditor|The document changed while saving was being checked. Review the current text and save again.',
            );
          if (error?.code === 'draft-clear')
            message = s__(
              'MarkdownEditor|Submission started, but the local draft could not be cleared.',
            );
          this.alert = {
            message,
            variant: 'danger',
            submissionError: true,
            dismiss: () => {
              this.alert = null;
            },
          };
        },
        clearDraft: () => this.clearDraft(this.autosaveKey),
        restoreDraft: () => this.saveDraft(),
      });
    }

getValue() {
      if (!this.submissionBinding) throw new Error('MARKDOWN_SUBMISSION_NOT_READY');
      return this.submissionBinding.getValue();
    }

async handleSubmit(event) {
    event.preventDefault();
    if (this.submissionPending) return false;
    this.submissionPending = true;
    const form = event.target;
    let snapshot;
    let submitted = false;
    try {
      trackSavedUsingEditor(
        localStorage.getItem('gl-markdown-editor-mode') === EDITING_MODE_CONTENT_EDITOR,
        getIssuableType(),
      );
      snapshot = prepareMarkdownSubmission(form);
      if (!snapshot) return false;
      const descriptionText = this.descriptionField().val() || '';
      const confirmSubmit = await detectAndConfirmSensitiveTokens({
        content: descriptionText,
        contentType: CONTENT_TYPE.DESCRIPTION,
      });
      if (!confirmSubmit) return false;
      if (
        !validateMarkdownSubmission(snapshot) ||
        (this.descriptionField().val() || '') !== descriptionText
      ) {
        createAlert({
          message: __(
            'The description changed while saving was being checked. Review it and submit again.',
          ),
        });
        return false;
      }
      this.showSubmitLoading();
      form.submit();
      submitted = true;
      completeMarkdownSubmission(snapshot);
      this.resetAutosave();
      return true;
    } catch {
      createAlert({
        message: submitted
          ? __('Submission started, but local draft cleanup could not finish.')
          : __('Unable to submit the current document. Please try again.'),
      });
      return submitted;
    } finally {
      if (!submitted) {
        try {
          if (snapshot) restoreMarkdownSubmissionDrafts(snapshot);
        } finally {
          this.submissionPending = false;
          this.submitButton.removeAttr('disabled');
          this.submitButton.removeClass('disabled');
        }
      }
    }
  }

function mountAutosaveClearOnSubmit(autosaveKey) {
  const resetAutosaveButtons = document.querySelectorAll('.js-reset-autosave');
  if (resetAutosaveButtons.length === 0) {
    return;
  }

  for (const resetAutosaveButton of resetAutosaveButtons) {
    if (['submit', 'image'].includes(resetAutosaveButton.type)) continue;
    resetAutosaveButton.addEventListener('click', () => {
      eventHub.$emit(CLEAR_AUTOSAVE_ENTRY_EVENT, autosaveKey);
    });
  }
}
